// Created: 2026-07-26

/**
 * Unit tests for visual-style-nudge (UserPromptSubmit sub-hook)
 *
 * Re-anchors the visual-style rule on prompts that want a shaped answer.
 * The throttle is the load-bearing behaviour: firing once per session would
 * reproduce the decay this hook exists to fix, and firing every turn would be
 * noise, so it must fire on the 1st qualifying prompt and periodically after.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { HookInput } from '../../types.js';
import { visualStyleNudge } from '../../prompt/visual-style-nudge.js';

let dir: string;
let session = 0;

// CLAUDE_PLUGIN_DATA is the var getSessionStorageDir() actually honors. An
// earlier draft of this file set CLAUDE_SESSION_STORAGE_DIR, which is read by
// nothing — the throttle counters were written into the real
// src/hooks/.claude/memory/sessions/ and survived between runs, so the suite
// passed once on a clean tree and then failed on every rerun. Isolation here
// is load-bearing, not hygiene: the whole point of these tests is counting.
// The nudge is OFF by default. Every test below that exercises the firing
// logic opts in explicitly; the "opt-in" describe block at the end owns the
// off-by-default and text-source behaviour.
beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'viz-nudge-'));
  process.env.CLAUDE_PLUGIN_DATA = dir;
  process.env.ORK_VISUAL_STYLE_NUDGE = '1';
  delete process.env.ORK_VISUAL_STYLE_NUDGE_FILE;
  session += 1;
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  delete process.env.CLAUDE_PLUGIN_DATA;
  delete process.env.ORK_VISUAL_STYLE_NUDGE;
  delete process.env.ORK_VISUAL_STYLE_NUDGE_FILE;
});

/** The full message the hook injected before this change, byte for byte, for ordinal #1. */
const TEXT_BEFORE =
  '[visual-style-nudge #1] If this answer has shape, render it: one render, ' +
  'up to ~50 lines and 76 cells wide, verdict first. Lead with one prose line ' +
  'that states the point, then the render (header and headline meter, sections ' +
  'opened by a light rule and a traffic-light word, rows as icon / label / bar / ' +
  'value / action, a total line per section, one arithmetic summary line, ' +
  'info caveat lines), then two or three bold-led bullets on what the numbers ' +
  'told you. Status icons come from the closed semantic set; one domain icon ' +
  'per row in the leading column. A definition, a single fact or a one-line ask ' +
  'gets no render; over 50 lines is a page, not a chat answer. Applies to this ' +
  'reply and later ones. Full vocabulary and anatomy: the ork:glyph skill, ' +
  'rules/visual-style.md. Sub-agents do not inherit this rule; restate it in ' +
  'their prompt if their output reaches the user.';

function injected(r: ReturnType<typeof visualStyleNudge>): string {
  return (r.hookSpecificOutput as { additionalContext?: string } | undefined)?.additionalContext ?? '';
}

function prompt(text: string, sid = `s-${session}`): HookInput {
  return { tool_name: '', session_id: sid, prompt: text, tool_input: {} } as unknown as HookInput;
}

function fired(r: ReturnType<typeof visualStyleNudge>): boolean {
  const out = r.hookSpecificOutput as { additionalContext?: string } | undefined;
  return typeof out?.additionalContext === 'string' && out.additionalContext.includes('visual-style-nudge');
}

describe('visual-style-nudge', () => {
  it('fires on an explicit visualization ask', () => {
    expect(fired(visualStyleNudge(prompt('can you vis this in ascii emojies')))).toBe(true);
  });

  it('fires on implicit shape requests (the decay case)', () => {
    for (const p of ['tell me the status of the migration', 'compare these two approaches for me', 'what are my options here', 'show me the difference between the two dispatchers']) {
      session += 1;
      expect(fired(visualStyleNudge(prompt(p, `s-${session}`)))).toBe(true);
    }
  });

  it('stays silent on prompts with no shape', () => {
    expect(fired(visualStyleNudge(prompt('rename this variable to userCount')))).toBe(false);
  });

  it('REGRESSION (plugin eval 2026-09-12): stays silent on prose asks even when a shape word appears', () => {
    // Both were should-not-fire eval cases that scored LOWER with the plugin
    // (-40 and -20): the old set fired on `explain`, and the old message said
    // "not prose paragraphs". A definition or a one-paragraph explanation has
    // no shape to draw.
    for (const p of [
      'In one paragraph, explain what a feature flag kill switch is and when a team should reach for one instead of rolling back a deploy.',
      'explain how the dispatcher works',
      'What is the default value of the Retry-After header when a server returns 429? Answer in one sentence.',
      'summarise the thread for me',
    ]) {
      session += 1;
      expect(fired(visualStyleNudge(prompt(p, `s-${session}`)))).toBe(false);
    }
  });

  it('still fires on a genuine comparison ask, and the default text says verdict first and prose for a one-liner', () => {
    const r = visualStyleNudge(prompt('Explain the difference between rebasing onto main and merging main into my branch, and say which keeps the PR review history readable.', 'cmp-1'));
    expect(fired(r)).toBe(true);
    const c = injected(r);
    expect(c).toMatch(/verdict first/);
    expect(c).toMatch(/prose only/);
    expect(c).not.toMatch(/12 lines/);
    expect(c).not.toMatch(/not prose paragraphs/);
  });

  it('an explicit ask overrides the prose guard', () => {
    expect(fired(visualStyleNudge(prompt('explain how the dispatcher works, draw it in ascii', 'explicit-over-prose')))).toBe(true);
  });

  it('stays silent on very short prompts', () => {
    expect(fired(visualStyleNudge(prompt('status')))).toBe(false);
  });

  it('stays silent when the user already routed to a skill', () => {
    expect(fired(visualStyleNudge(prompt('/ork:assess the current status of things')))).toBe(false);
  });

  it('throttles: fires on the 1st qualifying prompt, not the 2nd', () => {
    const sid = 'throttle-a';
    expect(fired(visualStyleNudge(prompt('what is the status here', sid)))).toBe(true);
    expect(fired(visualStyleNudge(prompt('and the status of the other one', sid)))).toBe(false);
  });

  it('RE-ANCHORS periodically — this is the whole point vs a once-per-session nudge', () => {
    const sid = 'throttle-b';
    const results: boolean[] = [];
    for (let i = 0; i < 17; i++) {
      results.push(fired(visualStyleNudge(prompt('what is the status of things', sid))));
    }
    // Fires at prompt 1, 9, 17 (every 8th) — not once, not every time.
    expect(results.filter(Boolean).length).toBeGreaterThan(1);
    expect(results[0]).toBe(true);
    expect(results.filter(Boolean).length).toBeLessThan(results.length);
  });

  it('counts sessions independently', () => {
    expect(fired(visualStyleNudge(prompt('what is the status here', 'sess-1')))).toBe(true);
    expect(fired(visualStyleNudge(prompt('what is the status here', 'sess-2')))).toBe(true);
  });

  it('does not throw on a path-traversal session id', () => {
    const evil = '../../../etc/passwd';
    expect(() => visualStyleNudge(prompt('what is the status here', evil))).not.toThrow();
  });

  it('REGRESSION: an EXPLICIT ask is never throttled', () => {
    // Measured on a real 13-prompt session (2026-07-26): the operator typed
    // "vis in ascii emojies" six times and the throttle silenced four of them.
    // Rate-limiting the strongest signal that exists is backwards.
    const sid = 'explicit-never-throttled';
    const results: boolean[] = [];
    for (let i = 0; i < 6; i++) {
      results.push(fired(visualStyleNudge(prompt('vis in ascii emojies status', sid))));
    }
    expect(results.every(Boolean)).toBe(true);
  });

  it('REGRESSION: replays the real session prompts that were wrongly silenced', () => {
    const sid = 'real-session-replay';
    // Verbatim from the 2026-07-26 session, in order.
    const explicitAsks = [
      'vis in ascii emojies status and decision ened i dont understand',
      'vis in ascii emojies explanation',
      'status? vis in ascii emojies',
      'explain whats left on track b in ascii emojies',
      'so whats next? vis ascii emojies',
    ];
    const results = explicitAsks.map(p => fired(visualStyleNudge(prompt(p, sid))));
    // Before the bypass this was [true, false, false, false, false].
    expect(results).toEqual([true, true, true, true, true]);
  });

  it('IMPLICIT shape requests stay throttled (the bypass must not become noise)', () => {
    const sid = 'implicit-still-throttled';
    const results: boolean[] = [];
    for (let i = 0; i < 6; i++) {
      results.push(fired(visualStyleNudge(prompt('what is the status of things', sid))));
    }
    expect(results[0]).toBe(true);
    expect(results.slice(1).some(Boolean)).toBe(false);
  });

  it('REGRESSION: consecutive fires emit DIFFERENT text (defeats dispatcher delta-skip)', () => {
    // unified-dispatcher runs delta detection on the consolidated context and
    // silently drops a turn whose output is byte-identical to the previous one
    // (unified-dispatcher.ts, prompt-hash.txt). A constant message is therefore
    // injected exactly ONCE per session and every later re-anchor is swallowed,
    // reproducing the decay this hook exists to fix. Measured through the real
    // dispatcher before the fix: 1/20 fires. After: 3/20, at prompts 1/9/17.
    const sid = 'delta-skip';
    const messages: string[] = [];
    for (let i = 0; i < 17; i++) {
      const r = visualStyleNudge(prompt('what is the status of things', sid));
      const c = (r.hookSpecificOutput as { additionalContext?: string })?.additionalContext;
      if (c) messages.push(c);
    }
    expect(messages.length).toBeGreaterThan(1); // it re-anchors at all
    expect(new Set(messages).size).toBe(messages.length); // and never repeats itself
  });

});

describe('visual-style-nudge opt-in: off by default, text is the user\'s own', () => {
  const ASK = 'vis in ascii emojies status of the migration';

  it('is OFF by default: no env var means no injected text, even on an explicit ask', () => {
    delete process.env.ORK_VISUAL_STYLE_NUDGE;
    const r = visualStyleNudge(prompt(ASK, 'off-default'));
    expect(fired(r)).toBe(false);
    expect(injected(r)).toBe('');
    expect(r.hookSpecificOutput).toBeUndefined();
  });

  it('stays off for anything but the exact string 1', () => {
    for (const v of ['0', 'true', 'yes', '']) {
      process.env.ORK_VISUAL_STYLE_NUDGE = v;
      session += 1;
      expect(fired(visualStyleNudge(prompt(ASK, `off-${v}-${session}`)))).toBe(false);
    }
    // Positive control: the same prompt in a fresh session fires with the exact value 1.
    process.env.ORK_VISUAL_STYLE_NUDGE = '1';
    session += 1;
    expect(fired(visualStyleNudge(prompt(ASK, `on-control-${session}`)))).toBe(true);
  });

  it('does not touch the throttle counter while off', () => {
    // An off hook must not burn the 1st-fire slot: opting in mid-session still fires on the next prompt.
    delete process.env.ORK_VISUAL_STYLE_NUDGE;
    visualStyleNudge(prompt('what is the status here', 'counter-off'));
    process.env.ORK_VISUAL_STYLE_NUDGE = '1';
    expect(fired(visualStyleNudge(prompt('what is the status here', 'counter-off')))).toBe(true);
  });

  it('BEFORE vs AFTER: opted in with no file, the injected text is the short neutral line, not the old long text', () => {
    const after = injected(visualStyleNudge(prompt(ASK, 'before-after')));
    expect(after).toBe(
      '[visual-style-nudge #1] If this answer has shape (a status, a comparison, options), render it visually ' +
        'with the verdict first. A definition, a single fact or a one-line ask gets prose only.',
    );
    expect(after.length).toBeLessThan(TEXT_BEFORE.length / 2);
    // Nothing of the old vocabulary survives in the shipped default.
    for (const gone of ['76 cells', 'traffic-light', 'bar /', 'ork:glyph', 'visual-style.md', 'closed semantic set', 'Sub-agents do not inherit']) {
      expect(after).not.toContain(gone);
      expect(TEXT_BEFORE).toContain(gone);
    }
  });

  it('uses the text in ORK_VISUAL_STYLE_NUDGE_FILE when set, behind the same ordinal prefix', () => {
    const file = join(dir, 'my-style.txt');
    writeFileSync(file, '  Render status as a table, then one line of verdict.\n');
    process.env.ORK_VISUAL_STYLE_NUDGE_FILE = file;
    expect(injected(visualStyleNudge(prompt(ASK, 'user-text')))).toBe(
      '[visual-style-nudge #1] Render status as a table, then one line of verdict.',
    );
  });

  it('keeps the ordinal varying with user text, so dispatcher delta-skip still cannot swallow re-anchors', () => {
    const file = join(dir, 'my-style.txt');
    writeFileSync(file, 'Constant user text.');
    process.env.ORK_VISUAL_STYLE_NUDGE_FILE = file;
    const sid = 'user-text-varies';
    const a = injected(visualStyleNudge(prompt(ASK, sid)));
    const b = injected(visualStyleNudge(prompt(ASK, sid)));
    expect(a).not.toBe('');
    expect(b).not.toBe('');
    expect(a).not.toBe(b);
  });

  it('falls back to the neutral line for a missing, empty, whitespace-only or non-file path', () => {
    const empty = join(dir, 'empty.txt');
    writeFileSync(empty, '   \n');
    // dir itself is a directory: reading it must fall back, not throw or block.
    for (const f of [join(dir, 'does-not-exist.txt'), empty, dir]) {
      process.env.ORK_VISUAL_STYLE_NUDGE_FILE = f;
      session += 1;
      expect(injected(visualStyleNudge(prompt(ASK, `fallback-${session}`)))).toContain('prose only');
    }
  });

  it('caps a runaway text file at 1500 characters', () => {
    const file = join(dir, 'big.txt');
    writeFileSync(file, 'x'.repeat(50_000));
    process.env.ORK_VISUAL_STYLE_NUDGE_FILE = file;
    const out = injected(visualStyleNudge(prompt(ASK, 'cap')));
    expect(out).toBe(`[visual-style-nudge #1] ${'x'.repeat(1500)}`);
  });

  it('counts the cap in characters, so a multi-byte or emoji text is never cut in half', () => {
    const file = join(dir, 'emoji.txt');
    writeFileSync(file, '😀'.repeat(3000)); // 4 bytes and 2 UTF-16 units each
    process.env.ORK_VISUAL_STYLE_NUDGE_FILE = file;
    const out = injected(visualStyleNudge(prompt(ASK, 'cap-emoji')));
    expect(out).toBe(`[visual-style-nudge #1] ${'😀'.repeat(1500)}`);
    expect(out).not.toContain('�');
  });
});
